// CreateGenericSecret - Create a generic-secret.
func (s *CredentialsApiService) CreateGenericSecret(ctx context.Context, request api.GenericSecretCreationRequest) (api.ImplResponse, error) {
	assetKind := api.ASSETKIND_GENERIC_SECRET
	audit.AuditFromCtx(ctx).WithEntityType(string(assetKind)).WithEntityName(request.Meta.Name).WithClusterId(safeStrPtr(request.Meta.ClusterId))

	validationError := ValidateAssetCreateRequestMeta(ctx, &request.Meta, assetKind)
	if validationError != nil {
		return NewErrorResponse(validationError), nil
	}

	validationError = ValidateGenericSecretRequest(&api.GenericSecretCreationSpec{
		ExistingSecretName: request.Spec.ExistingSecretName,
		KeyValuePairs:      request.Spec.KeyValuePairs,
	})
	if validationError != nil {
		return NewErrorResponse(validationError), nil
	}

	rbacErr := auth.ValidateAccessByActionAndAssetKind(ctx, ScopeInfoOfCreateRequest(&request.Meta), string(assetKind), backend.ACTION_CREATE, convutils.Deref(request.Meta.Private, false))
	if rbacErr != nil {
		return NewErrorResponse(api.NewError(int(rbacErr.Code), rbacErr.Message, errors.New(rbacErr.Details))), nil
	}

	if convutils.IsStringHasValue(request.Spec.ExistingSecretName) {
		validationError = validateSecretAssetVsClusterResource(ctx, &request.Meta, request.Spec.ExistingSecretName, openapi.SECRETTYPE_GENERIC)
		if validationError != nil {
			return NewErrorResponse(validationError), nil
		}
	}

	// For now, we support only project scope generic secret, therefore we validate scope is project and projectId is provided.
	validationError = validateGenericSecretMeta(&request.Meta)
	if validationError != nil {
		return NewErrorResponse(validationError), nil
	}

	var activeKeyId int32 = -1

	if request.Spec.KeyValuePairs != nil {
		tenantKeys, keysErr := encryption.GetTenantEncryptionKeys(ctx)
		if keysErr != nil {
			return NewErrorResponse(keysErr), nil
		}

		var encryptErr *api.Error

		for i := range *request.Spec.KeyValuePairs {
			(*request.Spec.KeyValuePairs)[i].Key, encryptErr = encryption.EncryptOAEPChunks(ctx, tenantKeys, (*request.Spec.KeyValuePairs)[i].Key, string(assetKind))

			if encryptErr != nil {
				return NewErrorResponse(encryptErr), nil
			}

			(*request.Spec.KeyValuePairs)[i].Value, encryptErr = encryption.EncryptOAEPChunks(
				ctx,
				tenantKeys,
				(*request.Spec.KeyValuePairs)[i].Value,
				string(assetKind),
			)

			if encryptErr != nil {
				return NewErrorResponse(encryptErr), nil
			}
		}

		activeKeyId = tenantKeys.ActiveKeyId
	}

	nameValidationQuery, err := scope2.GetNameValidationQuery(
		ctx,
		request.Meta.Name,
		request.Meta.Scope,
		request.Meta.ProjectId,
		request.Meta.DepartmentId,
		request.Meta.ClusterId,
		request.Meta.Private,
		api.ASSETKIND_GENERIC_SECRET,
		nil,
	)
	if err != nil {
		return NewErrorResponse(err), nil
	}

	genericSecret, err := dao.CreateGenericSecret(ctx, request, activeKeyId, nameValidationQuery)
	if err != nil {
		return NewErrorResponse(err), nil
	}
	audit.AuditFromCtx(ctx).WithEntityId(genericSecret.Meta.Id)

	return api.Response(http.StatusAccepted, genericSecret), nil
}

// DeleteGenericSecret - Delete a generic-secret.
func (s *CredentialsApiService) DeleteGenericSecret(ctx context.Context, assetId string) (api.ImplResponse, error) {
	assetKind := api.ASSETKIND_GENERIC_SECRET
	audit.AuditFromCtx(ctx).WithEntityType(string(assetKind)).WithEntityId(assetId)

	secretAsset, getError := dao.GetGenericSecretById(ctx, assetId, dao.CredentialsOptions{
		IncludeDeleted: true,
	})
	if getError != nil {
		return NewErrorResponse(getError), nil
	}
	audit.AuditFromCtx(ctx).WithEntityName(secretAsset.Meta.Name).WithClusterId(safeStrPtr(secretAsset.Meta.ClusterId))

	rbacErr := auth.ValidateAccessByActionAndAssetKind(ctx, ScopeInfoOfMeta(&secretAsset.Meta), string(assetKind), backend.ACTION_DELETE, convutils.Deref(secretAsset.Meta.Private, false))
	if rbacErr != nil {
		return NewErrorResponse(api.NewError(int(rbacErr.Code), rbacErr.Message, errors.New(rbacErr.Details))), nil
	}

	//
	//  existing assets - hard delete, non-existing - soft delete, because the agent needs to sync with them first
	//  private secrets - soft delete. (supported only in 2.23 clusters and are only non-existing)
	//
	var actionError *api.Error

	if convutils.BoolIsFalse(secretAsset.Meta.Private) && (convutils.IsStringHasValue(secretAsset.Spec.ExistingSecretName) || !agentSyncSupported(ctx, secretAsset.Meta.ClusterId)) {
		actionError = dao.DeleteGenericSecret(ctx, &secretAsset.Meta, dao.HardDelete)
	} else {
		actionError = dao.DeleteGenericSecret(ctx, &secretAsset.Meta, dao.SoftDelete)
	}

	if actionError != nil {
		return NewErrorResponse(actionError), nil
	}

	return NewDeletionResponse(), nil
}

