// CreateNgcApiKey - Create a ngc-api-key.
func (s *CredentialsApiService) CreateNgcApiKey(ctx context.Context, request api.NgcApiKeyCreationRequest) (api.ImplResponse, error) {
	assetKind := api.ASSETKIND_NGC_API_KEY
	audit.AuditFromCtx(ctx).WithEntityType(string(assetKind)).WithEntityName(request.Meta.Name).WithClusterId(safeStrPtr(request.Meta.ClusterId))

	validationError := ValidateAssetCreateRequestMeta(ctx, &request.Meta, assetKind)
	if validationError != nil {
		return NewErrorResponse(validationError), nil
	}

	rbacErr := auth.ValidateAccessByActionAndAssetKind(ctx, ScopeInfoOfCreateRequest(&request.Meta), string(assetKind), backend.ACTION_CREATE, convutils.Deref(request.Meta.Private, false))
	if rbacErr != nil {
		return NewErrorResponse(api.NewError(int(rbacErr.Code), rbacErr.Message, errors.New(rbacErr.Details))), nil
	}

	validationError = validateNgcApiKeyRequest(request.Meta)
	if validationError != nil {
		return NewErrorResponse(validationError), nil
	}

	tenantKeys, keysErr := encryption.GetTenantEncryptionKeys(ctx)
	if keysErr != nil {
		return NewErrorResponse(keysErr), nil
	}

	var encryptErr *api.Error

	encrypted, encryptErr := encryption.EncryptOAEPChunks(ctx, tenantKeys, &request.Spec.NgcApiKey, string(assetKind))
	if encryptErr != nil {
		return NewErrorResponse(encryptErr), nil
	}
	request.Spec.NgcApiKey = *encrypted

	activeKeyId := tenantKeys.ActiveKeyId

	nameValidationQuery, err := scope2.GetNameValidationQuery(
		ctx,
		request.Meta.Name,
		request.Meta.Scope,
		request.Meta.ProjectId,
		request.Meta.DepartmentId,
		request.Meta.ClusterId,
		request.Meta.Private,
		api.ASSETKIND_NGC_API_KEY,
		nil,
	)
	if err != nil {
		return NewErrorResponse(err), nil
	}

	ngcApiKey, err := dao.CreateNgcApiKey(ctx, request, activeKeyId, nameValidationQuery)
	if err != nil {
		return NewErrorResponse(err), nil
	}
	audit.AuditFromCtx(ctx).WithEntityId(ngcApiKey.Meta.Id)

	return api.Response(http.StatusAccepted, ngcApiKey), nil
}

