type CredentialsListHandler struct {
	dsType api.AssetKind

	addFunc func(ctx context.Context, result *api.CredentialsListResponse,
		queryParams *query_types.QueryParams, permittedScopes *auth.PermittedScopes,
		usageInfo bool, statusInfo bool) *api.Error
}

var credentialsListHandlers = []CredentialsListHandler{
	{api.ASSETKIND_PASSWORD, addPasswords},
	{api.ASSETKIND_ACCESS_KEY, addAccessKeys},
	{api.ASSETKIND_DOCKER_REGISTRY, addDockerRegistries},
	{api.ASSETKIND_GENERIC_SECRET, addGenericSecrets},
	{api.ASSETKIND_NGC_API_KEY, addNgcApiKeys},
}

func (s *CredentialsApiService) ListCredentialsAssets(ctx context.Context, nameParam string,
	scopeParam string, projectIdParam int32, departmentId string, clusterId string, usageInfo bool, statusInfo bool, privateOnly bool, includePrivate bool,
	includeDescendants bool, filterByType string,
) (api.ImplResponse, error) {
	queryParams, queryError := query_types.NewQueryParams("", nameParam, scopeParam, includeDescendants, projectIdParam, departmentId, clusterId, nil)
	if queryError != nil {
		return NewErrorResponse(queryError), nil
	}
	queryParams, queryError = queryParams.WithPrivate(privateOnly, includePrivate)
	if queryError != nil {
		return NewErrorResponse(queryError), nil
	}

	permittedScopes, authError := query_types.ApplyRbacRules(ctx, queryParams)
	if authError != nil {
		return NewErrorResponse(authError), nil
	}

	result := api.CredentialsListResponse{
		Entries: make([]api.CredentialsListResponseEntry, 0),
	}

	var actionError *api.Error

	for _, h := range credentialsListHandlers {
		if filterByType == "" || filterByType == string(h.dsType) {
			actionError = h.addFunc(ctx, &result, queryParams, permittedScopes, usageInfo, statusInfo)
			if actionError != nil {
				return NewErrorResponse(actionError), nil
			}
		}
	}

	return api.Response(http.StatusOK, result), nil
}

// GetNgcApiKeyByIdInternal - Get a NGC API key by id (internal).
func (s *CredentialsApiService) GetNgcApiKeyByIdInternal(ctx context.Context, assetId string) (api.ImplResponse, error) {
	ngcApiKeyAsset, err := dao.GetNgcApiKeyById(ctx, assetId, dao.CredentialsOptions{MaskCredentials: false})
	if err != nil {
		return NewErrorResponse(err), nil
	}

	_, _, authError := query_types.ApplyRbacRulesGetById(ctx, ngcApiKeyAsset.Meta)
	if authError != nil {
		return NewErrorResponse(authError), nil
	}

	tenantKeys, keysErr := encryption.GetTenantEncryptionKeys(ctx)
	if keysErr != nil {
		return NewErrorResponse(keysErr), nil
	}

	ngcApiKey, err := encryption.DecryptOAEPChunks(ctx, tenantKeys, ngcApiKeyAsset.Spec.KeyId, convutils.Ref(ngcApiKeyAsset.Spec.NgcApiKey), string(api.ASSETKIND_NGC_API_KEY))
	if err != nil {
		return NewErrorResponse(err), nil
	}

	return api.Response(http.StatusOK, api.NgcApiKeyInternal{Key: ngcApiKey}), nil
}

func addAccessKeys(ctx context.Context, result *api.CredentialsListResponse,
	queryParams *query_types.QueryParams, permittedScopes *auth.PermittedScopes, usageInfo bool, statusInfo bool,
) *api.Error {
	assetKind := api.ASSETKIND_ACCESS_KEY

	options := dao.CredentialsOptions{
		MaskCredentials: true,
		IncludeDeleted:  statusInfo, // if status info is displayed, we also include deleted assets with their dtatus
	}

	accessKeys, actionError := dao.ListAccessKeys(ctx, queryParams, options)
	if actionError != nil {
		return actionError
	}

	entries := make([]api.CredentialsListResponseEntry, 0)

	for _, accessKey := range accessKeys.Entries {
		entries = append(entries, api.CredentialsListResponseEntry{
			Meta:        accessKey.Meta,
			Spec:        api.CredentialsListResponseAssetSpec{AccessKey: &accessKey.Spec},
			ClusterInfo: accessKey.ClusterInfo,
		})
	}

	patchingPointers := response_patching.LoadResponsePatchingPtrs(entries)

	projects.PatchProjectNames(ctx, patchingPointers)

	if usageInfo {
		patchErr := usage_info.PatchUsageInfo(ctx, assetKind, patchingPointers, queryParams.AllowedOrgUnits.AllowedProjects)
		if patchErr != nil {
			return patchErr
		}
	}

	if statusInfo {
		assetClusterStatus := asset_cluster_status.NewAssetClusterStatus(patchingPointers, permittedScopes)

		patchErr := status_info.PatchStatusInfo(ctx, assetClusterStatus, patchingPointers, api.ASSETKIND_ACCESS_KEY)
		if patchErr != nil {
			return patchErr
		}

	}

	result.Entries = append(result.Entries, entries...)

	return nil
}

