/// Validations
////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

// validateAssetVsCredentials validates compatibility between an asset and a credential it is using, the enforced policy is:
// system scope asset can only use system scope credentials
// tenant scope asset can only use tenant scope credentials
// project scope asset can use either system or tenant scope credentials or a project scope credentials of the same project
func validateAssetVsCredentials(ctx context.Context, assetScope api.Scope, assetScopeId string, credentialsId *string,
) *api.Error {
	if credentialsId == nil {
		return nil // credentials are optional for some assets (password is optional for git, for example)
	}
	if *credentialsId == "" {
		return api.NewValidationError("asset id must not be empty")
	}
	credentials, getError := dao.GetAssetMetaById(ctx, *credentialsId)
	if getError != nil {
		return getError
	}

	if assetScope == api.SCOPE_TENANT || assetScope == api.SCOPE_SYSTEM {
		if credentials.Scope != assetScope {
			return api.NewValidationError(fmt.Sprintf("%s scope asset must use %s scope %s", assetScope, assetScope, credentials.Kind))
		}
		return nil
	}

	if assetScope == api.SCOPE_CLUSTER {
		tenantId := auth.TenantIdOf(ctx)
		err := validateClusterScopeAssetCredential(assetScope, assetScopeId, *credentials, tenantId)
		if err != nil {
			return err
		}
	} else {
		orgScopeType, err := orgUnitApi.NewScopeTypeFromValue(string(assetScope))
		if err != nil {
			return api.NewError(http.StatusInternalServerError, fmt.Sprintf("invalid scope type: %s", assetScope), err)
		}
		ancestors, apiError := org_unit.Get().GetAncestorsOfScope(ctx, *orgScopeType, assetScopeId)
		if apiError != nil {
			logging.WithCtx(runaictx.LoggerHook(ctx)).Debugf("get ancestors failed: %s", apiError.Message)
			return api.NewError(http.StatusServiceUnavailable, "failed to interrogate ancestors of the asset scope", nil)
		}
		if assetScope == api.SCOPE_DEPARTMENT {
			err := validateDepartmentScopeAssetCredential(assetScope, assetScopeId, *credentials, ancestors)
			if err != nil {
				return err
			}
		}
		if assetScope == api.SCOPE_PROJECT {
			err := validateProjectScopeAssetCredential(assetScope, assetScopeId, *credentials, ancestors)
			if err != nil {
				return err
			}
		}
	}
	return nil
}

func ValidatePasswordRequest(spec *api.PasswordCreationSpec) *api.Error {
	if spec == nil {
		return nil
	}
	if convutils.IsEmptyOrNull(spec.ExistingSecretName) {
		if convutils.IsEmptyOrNull(spec.User) {
			return api.NewValidationError("mandatory user name is not provided")
		}
		if convutils.IsEmptyOrNull(spec.Password) {
			return api.NewValidationError("mandatory password is not provided")
		}
	} else {
		if utils.StringHasValue(spec.User) {
			return api.NewValidationError("user name should not be provided when creating credentials from existing secret")
		}
		if utils.StringHasValue(spec.Password) {
			return api.NewValidationError("password should not be provided when creating credentials from existing secret")
		}
	}
	return nil
}

