func ScopeInfoOfMeta(meta *api.AssetMeta) *scope.ScopeInfo {
	return scope.ScopeInfoOf(scope.Scope(meta.Scope), meta.ProjectId, meta.DepartmentId, meta.ClusterId, meta.TenantId)
}

func validateProjectScopeAssetCredential(assetScope api.Scope, assetScopeId string, credentials dbmodel.AssetMeta, ancestors *orgUnitApi.Ancestors) *api.Error {
	if credentials.Scope == api.SCOPE_PROJECT {
		intScopeId, err := strconv.ParseInt(assetScopeId, 10, 32)
		if err != nil {
			return api.NewError(http.StatusServiceUnavailable, "failed to convert asset project id to int32", nil)
		}
		if *credentials.ProjectId != int32(intScopeId) {
			return api.NewValidationError(fmt.Sprintf("an asset and its %s credentials should reside in the same project", credentials.Kind))
		}
	}
	if credentials.Scope == api.SCOPE_DEPARTMENT {
		if *credentials.DepartmentId != ancestors.GetDepartmentId() {
			return api.NewValidationError(fmt.Sprintf("an asset and its %s credentials should reside in the same department", credentials.Kind))
		}
	}
	if credentials.Scope == api.SCOPE_CLUSTER {
		if *credentials.ClusterId != ancestors.GetClusterUuid() {
			return api.NewValidationError(fmt.Sprintf("an asset and its %s credentials should reside in the same cluster", credentials.Kind))
		}
	}
	if credentials.Scope == api.SCOPE_TENANT {
		intTenantId, err := strconv.ParseInt(ancestors.TenantId, 10, 32)
		if err != nil {
			return api.NewError(http.StatusServiceUnavailable, "failed to convert asset tenant id to int32", nil)
		}
		if *credentials.TenantId != int32(intTenantId) {
			return api.NewValidationError(fmt.Sprintf("%s scope asset and its %s should reside in the same tenant", assetScope, credentials.Kind))
		}
	}
	return nil
}

func validateDepartmentScopeAssetCredential(assetScope api.Scope, assetScopeId string, credentials dbmodel.AssetMeta, ancestors *orgUnitApi.Ancestors) *api.Error {
	if credentials.Scope == api.SCOPE_PROJECT {
		return api.NewValidationError(fmt.Sprintf("%s scope asset must use %s or higher scope %s", assetScope, assetScope, credentials.Kind))
	}
	if credentials.Scope == api.SCOPE_DEPARTMENT {
		if *credentials.DepartmentId != assetScopeId {
			return api.NewValidationError(fmt.Sprintf("%s scope asset must use same %s or higher scope %s", assetScope, assetScope, credentials.Kind))
		}
	}
	if credentials.Scope == api.SCOPE_CLUSTER {
		if *credentials.ClusterId != ancestors.GetClusterUuid() {
			return api.NewValidationError(fmt.Sprintf("%s scope asset and its %s should reside in the same cluster", assetScope, credentials.Kind))
		}
	}
	if credentials.Scope == api.SCOPE_TENANT {
		intTenantId, err := strconv.ParseInt(ancestors.TenantId, 10, 32)
		if err != nil {
			return api.NewError(http.StatusServiceUnavailable, "failed to convert asset tenant id to int32", nil)
		}
		if *credentials.TenantId != int32(intTenantId) {
			return api.NewValidationError(fmt.Sprintf("%s scope asset and its %s should reside in the same tenant", assetScope, credentials.Kind))
		}
	}
	return nil
}

func validateClusterScopeAssetCredential(assetScope api.Scope, assetScopeId string, credentials dbmodel.AssetMeta, tenantId int32) *api.Error {
	if credentials.Scope == api.SCOPE_DEPARTMENT || credentials.Scope == api.SCOPE_PROJECT {
		return api.NewValidationError(fmt.Sprintf("%s scope asset must use %s or higher scope %s", assetScope, assetScope, credentials.Kind))
	}
	if credentials.Scope == api.SCOPE_CLUSTER && *credentials.ClusterId != assetScopeId {
		return api.NewValidationError(fmt.Sprintf("%s scope asset and its %s should reside in the same cluster", assetScope, credentials.Kind))
	}
	if credentials.Scope == api.SCOPE_TENANT {
		if *credentials.TenantId != tenantId {
			return api.NewValidationError(fmt.Sprintf("%s scope asset and its %s should reside in the same tenant", assetScope, credentials.Kind))
		}
	}
	return nil
}

func validateGenericSecretMeta(assetMeta *api.AssetCreationRequest) *api.Error {
	// Generic secret is allowed in tenant scope only if it's a private secret
	if assetMeta.Scope == api.SCOPE_TENANT && !convutils.Deref(assetMeta.Private, false) {
		return api.NewValidationError("generic-secret asset does not support tenant scope")
	}
	return nil
}

func validateNgcApiKeyRequest(meta api.AssetCreationRequest) *api.Error {
	// ngc api key is allowed in tenant scope only if it's a private secret
	if meta.Scope == api.SCOPE_TENANT && !convutils.Deref(meta.Private, false) {
		return api.NewValidationError("ngc-api-key asset does not support tenant scope")
	}
	return nil
}

func ValidateGenericSecretRequest(spec *api.GenericSecretCreationSpec) *api.Error {
	if spec == nil {
		return nil
	}
	if convutils.IsEmptyOrNull(spec.ExistingSecretName) {
		if isKeyValuePairsEmptyOrNull(spec.KeyValuePairs) {
			return api.NewValidationError("mandatory keyValuePairs is not provided")
		}
	} else {
		if !isKeyValuePairsEmptyOrNull(spec.KeyValuePairs) {
			return api.NewValidationError("keyValuePairs should not be provided when creating credentials from existing secret")
		}
	}
	if spec.KeyValuePairs != nil {
		err := validateKeyValuePairs(spec.KeyValuePairs)
		if err != nil {
			return err
		}
	}

	return nil
}

func isKeyValuePairsEmptyOrNull(keyValuePairs *[]api.KeyValuePair) bool {
	if keyValuePairs == nil {
		return true
	}

	if len(*keyValuePairs) == 0 {
		return true
	}
	return false
}

func validateKeyValuePairs(keyValuePairs *[]api.KeyValuePair) *api.Error {
	for i := range *keyValuePairs {
		if convutils.IsEmptyOrNull((*keyValuePairs)[i].Key) {
			return api.NewValidationError("mandatory key property is not provided")
		}
		if convutils.IsEmptyOrNull((*keyValuePairs)[i].Value) {
			return api.NewValidationError("mandatory value property is not provided")
		}
	}
	return nil
}

func (s *SyncApiService) CredentialsSyncUpdates(ctx context.Context, clusterId string, after int64, clusterSyncReport api.ClusterSyncReport) (api.ImplResponse, error) {
	ngcApiKeySupported, capErr := checker.NewClusterCapabilitiesChecker(clusterId).
		ValidateClusterCapability(ctx, checker.MinVersionOfNgcApiKeySupport)
	if capErr != nil {
		return api.Response(http.StatusInternalServerError, capErr), nil
	}
	credentialAssetsToSync := dbmodel.CredentialAssetsToSync
	if !ngcApiKeySupported {
		credentialAssetsToSync = dbmodel.CredentialAssetsToSyncWithoutNgcApiKey
	}

	unifiedResult, err := s.handleAgentSyncUpdates(ctx, clusterId, after, &clusterSyncReport, credentialAssetsToSync, true /*need to decryptU*/)
	if err != nil {
		return api.Response(int(err.Code), err), nil
	}

	myResult := unifiedResult.ToCredentials()
	return api.Response(http.StatusOK, myResult), nil
}

func validateSecretAssetVsClusterResource(ctx context.Context, meta *api.AssetCreationRequest, resourceName *string, secretType openapi.SecretType) *api.Error {
	if resourceName == nil {
		return nil
	}

	scopeInfo := ScopeInfoOfCreateRequest(meta)

	resp, err := k8sObjectsTracker.Get().ListSecretsByScopeAndName(ctx, string(scopeInfo.Scope), scopeInfo.ScopeId, *resourceName)
	if err != nil {
		logging.WithCtx(runaictx.LoggerHook(ctx)).Errorf("failed to inquire secret status: %v", err.Message)
		return api.NewError(http.StatusServiceUnavailable, "failed to inquire the status of the secret in the cluster", errors.New(err.Message))
	}

	if len(resp.Secrets) == 0 {
		return api.NewError(http.StatusBadRequest, fmt.Sprintf("secret resource '%s' of %s scope could not be found in the cluster", *resourceName, scopeInfo.Scope), nil)
	}

	if convutils.HasValue(resp.Secrets[0].Origin) {
		if *resp.Secrets[0].Origin.Get() != openapi.ORIGIN_EXISTING {
			return api.NewError(http.StatusBadRequest, fmt.Sprintf("cannot create credentials with existingSecretName on resource '%s' because it is linked to an asset", *resourceName), nil)
		}
	}

	if resp.Secrets[0].Type != secretType {
		return api.NewError(http.StatusBadRequest, fmt.Sprintf("secret resource '%s' of %s scope is %s, rather than %s", *resourceName, scopeInfo.Scope, resp.Secrets[0].Type, secretType), nil)
	}

	return nil
}
